{
 "type": "object",
 "required": [
  "applicant_name",
  "legal_issue"
 ],
 "properties": {
  "applicant_name": {
   "type": "string",
   "title": "Applicant name"
  },
  "applicant_email": {
   "type": "string",
   "format": "email",
   "title": "Applicant e-mail"
  },
  "applicant_cell": {
   "type": "string",
   "format": "phone",
   "title": "Cell phone"
  },
  "legal_issue": {
   "type": "string",
   "title": "What happened?",
   "enum": [
    "Divorce",
    "Car accident",
    "Fired from job"
   ]
  }
 }
}
